import {useEffect,useState} from 'react';
import {Download,RefreshCw,ShieldCheck} from 'lucide-react';
import {exportClientData,listComplianceAudit} from '../../lib/practiceOperationsApi';

const SECTIONS=['CONSENTS','PORTAL_ACTIVITY','BILLING','DOCUMENTS','REFERRALS','AUTOMATIONS','AI_DRAFTS','FORMS','GOALS','TASKS','APPOINTMENTS','PROGRESS'];
export function ExternalComplianceAudit({clients=[]}){
  const[data,setData]=useState(null),[state,setState]=useState('loading'),[error,setError]=useState(''),[clientId,setClientId]=useState(''),[exporting,setExporting]=useState(false);
  async function load(){setState('loading');setError('');try{setData(await listComplianceAudit(clientId));setState('ready')}catch(reason){setError(reason.message||'Audit evidence could not be loaded.');setState('error')}}
  useEffect(()=>{void load()},[clientId]);
  async function createExport(){if(!clientId)return;setExporting(true);setError('');try{const result=await exportClientData(clientId,SECTIONS);const blob=new Blob([JSON.stringify(result.payload,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download=`client-data-export-${clientId}.json`;link.click();URL.revokeObjectURL(url)}catch(reason){setError(reason.message||'Client export could not be prepared.')}finally{setExporting(false)}}
  return <section className="space-y-5"><header><p className="text-xs font-bold uppercase tracking-widest text-blue-700">Operational evidence</p><h2 className="mt-1 text-3xl font-bold">Compliance &amp; audit centre</h2><p className="mt-2 text-sm text-slate-600">Tenant-scoped audit evidence and client data exports. This is not legal compliance certification.</p></header><div className="grid gap-4 rounded-3xl border bg-white p-5 sm:grid-cols-[1fr_auto]"><label className="text-sm font-semibold">Client scope<select value={clientId} onChange={event=>setClientId(event.target.value)} className="mt-2 min-h-12 w-full rounded-xl border px-3"><option value="">Whole practice audit</option>{clients.map(client=><option key={client.id} value={client.id}>{client.displayName}</option>)}</select></label><button disabled={!clientId||exporting} onClick={createExport} className="min-h-12 self-end rounded-xl bg-slate-950 px-5 font-semibold text-white disabled:cursor-not-allowed disabled:opacity-40"><Download className="mr-2 inline" size={17}/>{exporting?'Preparing…':'Export client data'}</button></div>{error&&<p role="alert" className="rounded-2xl border border-red-200 bg-red-50 p-4 text-sm text-red-800">{error}</p>}{state==='loading'?<div aria-label="Loading audit evidence" className="h-56 animate-pulse rounded-3xl bg-white"/>:state==='error'?<button onClick={load} className="min-h-11 rounded-xl border bg-white px-4"><RefreshCw className="mr-2 inline" size={16}/>Retry</button>:<article className="overflow-hidden rounded-3xl border bg-white"><div className="flex items-center justify-between border-b p-5"><div><h3 className="font-bold">Audit evidence</h3><p className="mt-1 text-xs text-slate-500">Classification: {data.classification?.replaceAll('_',' ')}</p></div><span className="rounded-full bg-emerald-50 px-3 py-1 text-xs font-bold text-emerald-800"><ShieldCheck className="mr-1 inline" size={14}/>Tenant scoped</span></div><div className="divide-y">{data.items?.map((item,index)=><div key={`${item.domain}-${item.resource_id}-${item.created_at}-${index}`} className="grid gap-1 p-4 sm:grid-cols-[120px_1fr_180px]"><strong className="text-xs text-blue-700">{item.domain}</strong><span className="text-sm font-semibold">{item.event_type?.replaceAll('_',' ')}</span><time className="text-xs text-slate-500 sm:text-right">{new Date(item.created_at).toLocaleString()}</time></div>)}{!data.items?.length&&<p className="p-8 text-center text-sm text-slate-500">No audit evidence exists for this confirmed scope.</p>}</div></article>}<aside className="rounded-3xl border border-amber-200 bg-amber-50 p-5 text-sm text-amber-950"><strong>Export boundary</strong><p className="mt-2">Private notes, raw session notes, internal intelligence, and team notes are excluded by default and cannot be requested through this export.</p></aside></section>
}
